const typography = {
  fontFamily: [
    "Inter",
    "Roboto",
    "Arial",
    "sans-serif",
  ].join(","),

  h1: {
    fontSize: "2.5rem",
    fontWeight: 700,
    lineHeight: 1.2,
    letterSpacing: "-0.01em",
  },

  h2: {
    fontSize: "2rem",
    fontWeight: 700,
    lineHeight: 1.3,
  },

  h3: {
    fontSize: "1.75rem",
    fontWeight: 600,
    lineHeight: 1.3,
  },

  h4: {
    fontSize: "1.5rem",
    fontWeight: 600,
    lineHeight: 1.4,
  },

  h5: {
    fontSize: "1.25rem",
    fontWeight: 600,
    lineHeight: 1.4,
  },

  h6: {
    fontSize: "1.125rem",
    fontWeight: 600,
    lineHeight: 1.5,
  },

  subtitle1: {
    fontSize: "1rem",
    fontWeight: 600,
  },

  subtitle2: {
    fontSize: "0.875rem",
    fontWeight: 600,
  },

  body1: {
    fontSize: "1rem",
    lineHeight: 1.6,
  },

  body2: {
    fontSize: "0.875rem",
    lineHeight: 1.5,
  },

  button: {
    textTransform: "none" as const,
    fontWeight: 600,
    fontSize: "0.9375rem",
  },

  caption: {
    fontSize: "0.75rem",
  },

  overline: {
    fontSize: "0.75rem",
    fontWeight: 700,
    textTransform: "uppercase" as const,
    letterSpacing: "0.08em",
  },
};

export default typography;
